<?php
namespace App\Models; use App\Enums\ReservationStatus; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model;
class Reservation extends Model { use HasFactory; protected $guarded=[]; protected function casts():array{return ['status'=>ReservationStatus::class,'check_in_at'=>'datetime','check_out_at'=>'datetime','subtotal'=>'decimal:2','discount_total'=>'decimal:2','tax_total'=>'decimal:2','grand_total'=>'decimal:2','deposit_required'=>'decimal:2'];} public function property(){return $this->belongsTo(Property::class);} public function guest(){return $this->belongsTo(Guest::class);} public function rooms(){return $this->hasMany(ReservationRoom::class);} public function folio(){return $this->hasOne(Folio::class);} public function stays(){return $this->hasMany(Stay::class);} public function payments(){return $this->hasMany(Payment::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} public function groupReservation(){return $this->belongsTo(GroupReservation::class);} public function corporateAccount(){return $this->belongsTo(CorporateAccount::class);} public function travelAgent(){return $this->belongsTo(TravelAgent::class);} }
